using System;
using System.Collections.Generic;
using Remains.RoomFormat;
using UnityEngine;
using UnityEngine.Tilemaps;

namespace Remains.Content
{
    // Serialized references to exported terrain art (Rooms/Original/Tiles). Generated by the
    // editor command from tiles-manifest.json; runtime never searches for assets by name.
    public sealed class RoomTileArtAsset : ScriptableObject
    {
        [Serializable] public sealed class TileEntry {public string id;public Tile tile;public Sprite sprite;}
        [Serializable] public sealed class TextureEntry {public string id;public Texture2D texture;}

        [SerializeField,InspectorName("Манифест графики")] private TextAsset manifest;
        [SerializeField,InspectorName("Маски и спрайты")] private TileEntry[] tiles=Array.Empty<TileEntry>();
        [SerializeField,InspectorName("Текстуры материалов")] private TextureEntry[] textures=Array.Empty<TextureEntry>();
        [NonSerialized] private TileManifest parsed;
        [NonSerialized] private Dictionary<string,TileEntry> tileIndex;
        [NonSerialized] private Dictionary<string,Texture2D> textureIndex;

        public void Configure(TextAsset manifestAsset,TileEntry[] tileEntries,TextureEntry[] textureEntries)
        {
            manifest=manifestAsset;tiles=tileEntries;textures=textureEntries;parsed=null;tileIndex=null;textureIndex=null;
        }

        public TileManifest Manifest=>parsed??=TileManifest.Read(manifest!=null?manifest.text:throw new InvalidOperationException($"{name}: нет манифеста графики."),name);

        public TileEntry Tile(string id)
        {
            if(tileIndex==null) {tileIndex=new Dictionary<string,TileEntry>(StringComparer.Ordinal);foreach(var entry in tiles) tileIndex.Add(entry.id,entry);}
            return tileIndex.TryGetValue(id,out var value)?value:throw new InvalidOperationException($"{name}: нет тайла/спрайта {id}.");
        }

        public Texture2D Texture(string id)
        {
            if(textureIndex==null) {textureIndex=new Dictionary<string,Texture2D>(StringComparer.Ordinal);foreach(var entry in textures) textureIndex.Add(entry.id,entry.texture);}
            return textureIndex.TryGetValue(id,out var value)?value:throw new InvalidOperationException($"{name}: нет текстуры {id}.");
        }
    }
}
